def factorize(n):
    f = {}
    x = n
    d = 2
    while d * d <= x:
        while x % d == 0:
            f[d] = f.get(d, 0) + 1
            x //= d
        d = 3 if d == 2 else d + 2
    if x > 1:
        f[x] = f.get(x, 0) + 1
    return f  # dict {prime: exponent}

def vpfact(m, p):
    # v_p(m!) via Legendre's formula
    s = 0
    pp = p
    while pp <= m:
        s += m // pp
        # guard pp overflow
        if pp > m // p:
            break
        pp *= p
    return s

def h_R_of_p_power(p, e, R):
    # minimal m such that v_p(m!) >= R*e
    target = R * e
    # lower bound 0, upper bound find by exponential search
    lo = 0
    hi = max(p * target, 1)
    # ensure hi large enough
    while vpfact(hi, p) < target:
        hi *= 2
        if hi > 10**7:
            break
    # binary search
    while lo < hi:
        mid = (lo + hi) // 2
        if vpfact(mid, p) >= target:
            hi = mid
        else:
            lo = mid + 1
    return lo

def f_T(b, T):
    M = b // T
    cnt = 0
    for i in range(1, M + 1):
        if gcd(i, b) == 1:
            cnt += 1
    return cnt

def max_prime_power_in_b_gamma(b, G):
    fac = factorize(b)
    # select prime p maximizing p^{G*alpha}
    best_p = None
    best_e = -1
    best_val = -1
    for p, a in fac.items():
        e = G * a
        val = p ** e
        if val > best_val:
            best_val = val
            best_p = p
            best_e = e
    return best_p, best_e

